python3 - <<'PY'
import csv, datetime
from decimal import Decimal, ROUND_HALF_UP

def c(x): return Decimal(x).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
def pct(x): return Decimal(x).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

rates={}
for r in csv.DictReader(open('rates.csv')):
    rates[r['currency']]=Decimal(r['eur_per_unit'])

txs=[]
for r in csv.DictReader(open('transactions.csv')):
    amt=Decimal(r['amount']); cur=r['currency']
    eur=c(amt*rates[cur])
    txs.append(dict(id=r['id'],date=datetime.date.fromisoformat(r['date']),cat=r['category'],
                    desc=r['description'],amt=amt,cur=cur,eur=eur))

print("rows:",len(txs),"date range:",min(t['date'] for t in txs),max(t['date'] for t in txs))
print("currencies:",sorted({t['cur'] for t in txs}))
ncur={}
for t in txs: ncur[t['cur']]=ncur.get(t['cur'],0)+1
print("currency counts:",ncur)

total=sum(t['eur'] for t in txs)
print("TOTAL:",c(total))
print("COUNT:",len(txs))
print("AVG:",c(total/len(txs)))
big=sorted(txs,key=lambda t:-t['eur'])[:6]
for t in big: print("  TOP",t['id'],t['date'],t['cat'],t['desc'],t['amt'],t['cur'],'->',t['eur'])

# monthly
mon={}
for t in txs:
    m=t['date'].strftime('%Y-%m'); mon.setdefault(m,Decimal(0)); mon[m]+=t['eur']
for m in sorted(mon): print("MONTH",m,c(mon[m]),"n=",sum(1 for t in txs if t['date'].strftime('%Y-%m')==m))
apr,may,jun=mon['2026-04'],mon['2026-05'],mon['2026-06']
print("May vs April:",pct((may-apr)/apr*100),"%")
print("June vs May:",pct((jun-may)/may*100),"%")

# categories
cats={}
for t in txs: cats.setdefault(t['cat'],[]).append(t)
import re
budget={}
for line in open('budget.yaml'):
    m=re.match(r'\s+(\w+):\s+(\d+)\s*$',line)
    if m: budget[m.group(1)]=Decimal(m.group(2))
print("budget:",budget)
trav=sum(t['eur'] for t in cats['travel'])
print("travel total:",c(trav),"share:",pct(trav/total*100),"%")
for k in sorted(cats,key=lambda k:-sum(t['eur'] for t in cats[k])):
    s=sum(t['eur'] for t in cats[k]); b=budget[k]
    print(f"CAT {k:9s} total={c(s):>10} budget={b:>9} diff={c(s-b):>9} status={'over' if s>b else 'under'} "
          f"pct_of_budget={pct(s/b*100)} n={len(cats[k])}")
print("budget grand:",sum(budget.values()))

# category x month
print("\ncat x month:")
for k in sorted(cats):
    row={m:c(sum(t['eur'] for t in cats[k] if t['date'].strftime('%Y-%m')==m)) for m in ['2026-04','2026-05','2026-06']}
    print(f"  {k:9s} apr={row['2026-04']:>8} may={row['2026-05']:>8} jun={row['2026-06']:>8}")

# travel detail
print("\ntravel rows:",len(cats['travel']))
td={}
for t in cats['travel']: td[t['desc']]=td.get(t['desc'],Decimal(0))+t['eur']
for k,v in sorted(td.items(),key=lambda kv:-kv[1]): print("   ",k,c(v))
# top merchants/descriptions overall
print("\ntop descriptions by EUR:")
dd={}
for t in txs: dd[t['desc']]=dd.get(t['desc'],Decimal(0))+t['eur']
for k,v in sorted(dd.items(),key=lambda kv:-kv[1])[:12]: print(f"   {k:20s} {c(v):>9}")
# fx exposure
fx=sum(t['eur'] for t in txs if t['cur']!='EUR')
print("\nnon-EUR converted total:",c(fx),"=",pct(fx/total*100),"% of spend")
